// GET /api/data?file=<name> -> a bundled data file, only for a logged-in visitor. The data lives inside this
// function (api/_data.js, generated by scripts/build_dashboard.py), never as a public static file.
const { isLoggedIn } = require("./_auth");

module.exports = (req, res) => {
  res.setHeader("Cache-Control", "private, no-store");
  if (!isLoggedIn(req)) return res.status(401).json({ error: "Login required." });
  const bundle = require("./_data");
  const file = String((req.query && req.query.file) || "");
  if (!Object.prototype.hasOwnProperty.call(bundle, file)) return res.status(404).json({ error: "No such data file." });
  return res.status(200).json(bundle[file]);
};
